<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { api } from './api'

type Level = 'FREE' | 'ONE_BUSY' | 'MANY_BUSY'
type Semester = { code: string; label: string; isCurrent: boolean; synced: boolean }
type College = { code: string; name: string }
type Teacher = { name: string; pinyinInitials: string; colleges: College[]; programName: string | null }
type Cell = { dayOfWeek: number; slotCode: string; level: Level; busyCount: number; occupancies: { teacherName: string; courseName: string; occupancyText: string }[] }
type Result = { missingImport: boolean; cells: Cell[]; absentTeachers: string[]; semesterCode: string; week: number }
type Preset = { id?: string; name: string; teacherNames: string[] }
type Progress = { status: string; currentCollege: string | null; finishedColleges: number; totalColleges: number; semesterCode: string; teacherCount: number; message: string; jobId?: string }
const semesters = ref<Semester[]>([]), semester = ref(''), week = ref(1), teacherQuery = ref(''), teacherHits = ref<Teacher[]>([]), highlighted = ref(0), selected = ref<string[]>([]), presets = ref<Preset[]>([])
const result = ref<Result | null>(null), filter = ref<Level | 'ALL'>('ALL'), selectedCell = ref<Cell | null>(null), drawer = ref<'cell' | 'college' | null>(null), semesterMenu = ref(false), syncModal = ref(false), importModal = ref(false), missingModal = ref(false), error = ref('')
const username = ref(''), password = ref(''), syncBusy = ref(false), syncProgress = ref<Progress | null>(null), syncError = ref(''), slider = ref<any>(null), move = ref(0), sliderTrack = ref<HTMLElement | null>(null), sliderDragging = ref(false), sliderStartX = ref(0), sliderStartY = ref(0), sliderLastAt = ref(0), sliderPoints = ref<{ a: number; b: number; c: number }[]>([]), programText = ref(''), importResult = ref<any>(null), colleges = ref<College[]>([]), allTeachers = ref<Teacher[]>([]), collegeSearch = ref(''), collegeTeacherQuery = ref(''), collegeProgram = ref(''), programAssignment = ref(''), savingProgram = ref(false), presetName = ref(''), savingPreset = ref(false), theme = ref<'light' | 'dark'>('light')
let searchTimer: number | undefined, pollTimer: number | undefined, searchSerial = 0, syncGeneration = 0
const slots = ['0102','0304','0506','0708','0910','1112'], days = ['周一','周二','周三','周四','周五','周六','周日']
const filteredTeachers = computed(() => allTeachers.value.filter(t => t.colleges.some(c => c.code === collegeSearch.value) && (!collegeProgram.value || (t.programName || '').includes(collegeProgram.value)) && (!collegeTeacherQuery.value || t.name.includes(collegeTeacherQuery.value))))
const selectedCollegeTeachers = computed(() => filteredTeachers.value.filter(t => selected.value.includes(t.name)))
function collegeName(teacher: Teacher) { return teacher.colleges.find(c => c.code === collegeSearch.value)?.name || colleges.value.find(c => c.code === collegeSearch.value)?.name || '' }
function teacherSubtitle(teacher: Teacher) { const college = collegeName(teacher); return teacher.programName ? `${college} · ${teacher.programName}` : college }
function toggleTheme() { theme.value = theme.value === 'light' ? 'dark' : 'light'; localStorage.setItem('theme', theme.value); document.documentElement.dataset.theme = theme.value }
function busyTeacher(cell: Cell | undefined) { return cell?.occupancies[0]?.teacherName || '' }
function slotRange(slot: string) { const start = Number(slot.slice(0, 2)); return `${start}-${start + 1}` }
const counts = computed(() => ({ ALL: result.value?.cells.length || 42, FREE: result.value?.cells.filter(c => c.level === 'FREE').length || 0, ONE_BUSY: result.value?.cells.filter(c => c.level === 'ONE_BUSY').length || 0, MANY_BUSY: result.value?.cells.filter(c => c.level === 'MANY_BUSY').length || 0 }))
function getCell(day: number, slot: string) { return result.value?.cells.find(c => c.dayOfWeek === day && c.slotCode === slot) }
function chooseCell(cell: Cell) { selectedCell.value = cell; drawer.value = 'cell' }
function addTeacher(teacher: Teacher) { if (!selected.value.includes(teacher.name)) selected.value.push(teacher.name); teacherQuery.value = ''; teacherHits.value = []; highlighted.value = 0 }
function removeTeacher(name: string) { selected.value = selected.value.filter(n => n !== name) }
function searchTeachers() { clearTimeout(searchTimer); const q = teacherQuery.value.trim(), serial = ++searchSerial; if (!q) { teacherHits.value = []; return } searchTimer = window.setTimeout(async () => { try { const r = await api.get<{ items?: Teacher[]; data?: Teacher[]; teachers?: Teacher[] }>(`/api/teachers?q=${encodeURIComponent(q)}&page=1&pageSize=8`); if (serial === searchSerial) teacherHits.value = (Array.isArray(r) ? r : r.items || r.data || r.teachers || []) as Teacher[] } catch (e) { error.value = (e as Error).message } }, 160) }
function teacherKey(e: KeyboardEvent) { if (e.key === 'ArrowDown' && teacherHits.value.length) { e.preventDefault(); highlighted.value = (highlighted.value + 1) % teacherHits.value.length } else if (e.key === 'ArrowUp' && teacherHits.value.length) { e.preventDefault(); highlighted.value = (highlighted.value + teacherHits.value.length - 1) % teacherHits.value.length } else if (e.key === 'Enter' && teacherHits.value.length) { e.preventDefault(); addTeacher(teacherHits.value[highlighted.value]) } }
async function query() { if (!selected.value.length) { error.value = '请选择教师'; return } try { error.value = ''; const r = await api.post<Result>('/api/common-free', { semesterCode: semester.value, week: Number(week.value), teacherNames: selected.value }); result.value = r; filter.value = 'ALL'; if (r.missingImport) missingModal.value = true } catch (e) { error.value = (e as Error).message } }
async function loadPreset(preset: Preset) { selected.value = [...preset.teacherNames]; await query() }
async function savePreset() { if (!presetName.value.trim() || !selected.value.length) return; savingPreset.value = true; try { const created = await api.post<Preset>('/api/presets', { name: presetName.value.trim(), teacherNames: selected.value }); presets.value.push(created); presetName.value = '' } catch (e) { error.value = (e as Error).message } finally { savingPreset.value = false } }
async function deletePreset(preset: Preset) { try { await api.delete(`/api/presets/${encodeURIComponent(preset.name)}`); presets.value = presets.value.filter(p => p.name !== preset.name) } catch (e) { error.value = (e as Error).message } }
async function openCollegePicker() { drawer.value = 'college'; await loadCollegeTeachers() }
async function loadCollegeTeachers() { if (!collegeSearch.value) { allTeachers.value = []; return } try { const pages: Teacher[] = []; let page = 1; for (;;) { const r = await api.get<{ data?: Teacher[]; pagination?: { totalPages?: number } }>(`/api/teachers?collegeCode=${encodeURIComponent(collegeSearch.value)}&page=${page}&pageSize=200`); pages.push(...(r.data || [])); if (page >= (r.pagination?.totalPages || 1)) break; page += 1 } allTeachers.value = pages } catch (e) { error.value = (e as Error).message } }
function toggleCollegeTeacher(name: string) { if (selected.value.includes(name)) removeTeacher(name); else selected.value.push(name) }
function resetSync() { syncGeneration += 1; if (pollTimer !== undefined) { clearInterval(pollTimer); pollTimer = undefined }; syncBusy.value = false; syncProgress.value = null; syncError.value = ''; slider.value = null; sliderDragging.value = false; sliderPoints.value = []; move.value = 0 }
function closeSync() { resetSync(); syncModal.value = false }
function closeModalBackdrop() { if (syncModal.value) closeSync(); importModal.value = false; missingModal.value = false }
function openSync() { resetSync(); missingModal.value = false; syncModal.value = true }
async function startSync() { if (syncBusy.value) return; if (pollTimer !== undefined) { clearInterval(pollTimer); pollTimer = undefined } syncBusy.value = true; syncProgress.value = null; syncError.value = ''; const generation = syncGeneration; try { const body: { semesterCode: string; username?: string; password?: string } = { semesterCode: semester.value }; if (typeof username.value === 'string' && username.value.trim() && typeof password.value === 'string' && password.value.trim()) { body.username = username.value; body.password = password.value } const r = await api.post<any>('/api/sync/start', body); if (generation !== syncGeneration) return; if (r.status === 'NEED_SLIDER') { slider.value = r; move.value = 0; sliderPoints.value = [] } else watchSync(r.jobId) } catch (e) { if (generation !== syncGeneration) return; syncError.value = (e as Error).message; syncBusy.value = false } }
function sliderPointerDown(e: PointerEvent) { if (!sliderTrack.value) return; e.preventDefault(); sliderDragging.value = true; sliderStartX.value = e.clientX; sliderStartY.value = e.clientY; sliderLastAt.value = Date.now(); sliderPoints.value = [{ a: 0, b: 0, c: 0 }]; move.value = 0; sliderTrack.value.setPointerCapture(e.pointerId) }
function sliderPointerMove(e: PointerEvent) { if (!sliderDragging.value || !sliderTrack.value) return; const now = Date.now(); const distance = Math.max(0, Math.min(e.clientX - sliderStartX.value, sliderTrack.value.clientWidth)); move.value = distance; sliderPoints.value.push({ a: distance, b: e.clientY - sliderStartY.value, c: now - sliderLastAt.value }); sliderLastAt.value = now }
function sliderPointerUp() { sliderDragging.value = false }
async function submitSlider() { if (!slider.value || !sliderTrack.value) return; syncError.value = ''; const canvasWidth = sliderTrack.value.clientWidth; const tracks = sliderPoints.value.map(point => { const round = (value: number) => { const rounded = Math.round(value); return Object.is(rounded, -0) ? 0 : rounded }; return { a: round(point.a), b: round(point.b), c: round(point.c) } }); const finalMove = tracks.length ? tracks[tracks.length - 1].a : 0; const generation = syncGeneration; try { const r = await api.post<any>('/api/sync/slider', { jobId: slider.value.jobId, canvasWidth, move: finalMove, tracks }); if (generation !== syncGeneration) return; slider.value = null; watchSync(r.jobId) } catch (e) { if (generation !== syncGeneration) return; syncError.value = (e as Error).message } }
function watchSync(jobId: string) { const generation = syncGeneration; if (pollTimer !== undefined) clearInterval(pollTimer); const timer = window.setInterval(async () => { try { const progress = await api.get<Progress>(`/api/sync/${jobId}`); if (generation !== syncGeneration || pollTimer !== timer) return; syncProgress.value = progress; if (progress.status === 'DONE' || progress.status === 'FAILED') { clearInterval(timer); if (pollTimer === timer) pollTimer = undefined; syncBusy.value = false; if (progress.status === 'FAILED') syncError.value = progress.message === 'error' ? '滑块未通过，请再拖一次' : progress.message || '同步失败'; if (progress.status === 'DONE') { const refreshedSemesters = await api.get<Semester[]>('/api/semesters'); if (generation !== syncGeneration) return; semesters.value = refreshedSemesters; if (teacherQuery.value.trim()) searchTeachers(); if (drawer.value === 'college') await loadCollegeTeachers(); if (generation !== syncGeneration) return; await query(); if (generation !== syncGeneration) return } } } catch (e) { if (generation === syncGeneration && (pollTimer === timer || pollTimer === undefined)) syncError.value = (e as Error).message } }, 800); pollTimer = timer }
async function importPrograms() { try { importResult.value = await api.post<any>('/api/programs/import', { text: programText.value }) } catch (e) { error.value = (e as Error).message } }
async function saveProgram() { const program = programAssignment.value.trim(); if (!program || !selectedCollegeTeachers.value.length) return; savingProgram.value = true; const college = collegeName(selectedCollegeTeachers.value[0]); try { await api.post('/api/programs/import', { text: selectedCollegeTeachers.value.map(t => `${t.name},${college},${program}`).join('\n') }); selectedCollegeTeachers.value.forEach(t => { t.programName = program }); programAssignment.value = '' } catch (e) { error.value = (e as Error).message } finally { savingProgram.value = false } }
async function clearProgram() { if (!selectedCollegeTeachers.value.length) return; savingProgram.value = true; const college = collegeName(selectedCollegeTeachers.value[0]); try { await api.post('/api/programs/import', { text: selectedCollegeTeachers.value.map(t => `${t.name},${college},`).join('\n') }); selectedCollegeTeachers.value.forEach(t => { t.programName = null }) } catch (e) { error.value = (e as Error).message } finally { savingProgram.value = false } }
function selectAllCollegeTeachers() { filteredTeachers.value.forEach(t => { if (!selected.value.includes(t.name)) selected.value.push(t.name) }) }
function clearCollegeTeachers() { filteredTeachers.value.forEach(t => removeTeacher(t.name)) }
function readImportFile(e: Event) { const file = (e.target as HTMLInputElement).files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { programText.value = String(reader.result || '') }; reader.readAsText(file) }
function keydown(e: KeyboardEvent) { if (e.key === 'Escape') { drawer.value = null; if (syncModal.value) closeSync(); importModal.value = false; missingModal.value = false; semesterMenu.value = false } if (!drawer.value && result.value && ['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter'].includes(e.key) && !(e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement)) { e.preventDefault(); const current = selectedCell.value || result.value.cells[0]; if (!current) return; let d = current.dayOfWeek, s = slots.indexOf(current.slotCode); if (e.key === 'ArrowUp') s = Math.max(0, s - 1); if (e.key === 'ArrowDown') s = Math.min(5, s + 1); if (e.key === 'ArrowLeft') d = Math.max(1, d - 1); if (e.key === 'ArrowRight') d = Math.min(7, d + 1); if (e.key === 'Enter') chooseCell(current); else selectedCell.value = getCell(d, slots[s]) || null } }
function statusClass(cell: Cell | undefined) { return result.value ? cell?.level.toLowerCase() || 'unknown' : 'placeholder' }
function copyOccupancy() { navigator.clipboard?.writeText(selectedCell.value?.occupancies.map(o => o.occupancyText).join('\n') || '') }
onMounted(async () => { window.addEventListener('keydown', keydown); theme.value = (localStorage.getItem('theme') as 'light' | 'dark') || 'light'; document.documentElement.dataset.theme = theme.value; try { semesters.value = await api.get<Semester[]>('/api/semesters'); semester.value = semesters.value.find(s => s.isCurrent)?.code || semesters.value.find(s => s.code === '2026-2027-1')?.code || semesters.value[0].code; const settings = await api.get<{ currentWeek?: number }>('/api/settings'); week.value = settings.currentWeek || 1; presets.value = await api.get<Preset[]>('/api/presets'); colleges.value = await api.get<College[]>('/api/colleges') } catch (e) { error.value = (e as Error).message } })
onUnmounted(() => { window.removeEventListener('keydown', keydown); clearTimeout(searchTimer); if (pollTimer !== undefined) clearInterval(pollTimer) })
</script>
<template>
  <main class="workspace">
    <header class="topbar"><a class="brand" href="#"><span class="brand-mark">公</span><span>公共空闲工作台</span></a><div class="top-actions"><button class="button secondary theme-button" :aria-label="theme==='light'?'切换暗色主题':'切换亮色主题'" @click="toggleTheme">{{theme==='dark'?'☀️':'🌙'}}</button><button class="button secondary" @click="openSync">同步课表</button><button class="button secondary" @click="importModal=true">导入专业</button></div></header>
    <section class="omnibar panel">
      <div class="query-row">
        <div class="field semester-field"><label>学期</label><button class="select-button" aria-haspopup="listbox" :aria-expanded="semesterMenu" @click="semesterMenu=!semesterMenu">{{semesters.find(s=>s.code===semester)?.label || '选择学期'}}<span class="semester-state">{{semesters.find(s=>s.code===semester)?.synced ? '已同步' : '未同步'}}</span><span class="chevron">⌄</span></button><div v-if="semesterMenu" class="semester-menu" role="listbox"><button v-for="s in semesters" :key="s.code" role="option" :aria-selected="semester===s.code" @click="semester=s.code;semesterMenu=false"><span>{{s.label}}</span><small :class="s.synced?'synced':'unsynced'">{{s.synced?'已同步':'未同步'}}</small></button></div></div>
        <label class="field week-field">周次<span class="number-wrap"><input v-model.number="week" type="number" min="1" max="30"/><small>周</small></span></label>
        <div class="field search-field"><label for="teacher-search">教师</label><div class="search-wrap"><span class="search-icon">⌕</span><input id="teacher-search" v-model="teacherQuery" autocomplete="off" placeholder="输入姓名或拼音" @input="searchTeachers" @keydown="teacherKey"/><div v-if="teacherHits.length" class="teacher-menu" role="listbox"><button v-for="(teacher,index) in teacherHits" :key="teacher.name" :class="{highlighted:index===highlighted}" @mousedown.prevent="addTeacher(teacher)"><span>{{teacher.name}}</span><small>{{teacher.colleges?.[0]?.name || '未指定学院'}}</small></button></div></div></div>
        <button class="button secondary college-button" @click="openCollegePicker">按学院/专业选人</button><button class="button primary query-button" @click="query">查询 <kbd>↵</kbd></button>
      </div>
      <div class="selected-row"><div class="chips"><span v-for="name in selected" :key="name" class="teacher-chip">{{name}}<button :aria-label="`移除${name}`" @click="removeTeacher(name)">×</button></span><span v-if="!selected.length" class="selection-hint">搜索并添加要比较的教师</span></div><div v-if="selected.length" class="save-preset"><template v-if="!savingPreset && !presetName"><button class="text-button" @click="savingPreset=true">＋ 存为常用分组</button></template><form v-else class="preset-form" @submit.prevent="savePreset"><input v-model="presetName" autofocus maxlength="40" placeholder="分组名称"/><button class="text-button" type="submit" :disabled="!presetName.trim()">保存</button><button class="text-button muted-button" type="button" @click="savingPreset=false;presetName=''">取消</button></form></div></div>
      <div v-if="presets.length" class="preset-row"><span class="row-label">常用分组</span><button v-for="preset in presets" :key="preset.id || preset.name" class="preset-chip" @click="loadPreset(preset)">{{preset.name}}<span class="preset-delete" role="button" aria-label="删除分组" @click.stop="deletePreset(preset)">×</span></button></div>
    </section>
    <div v-if="error" class="notice error-notice" role="alert">{{error}}<button @click="error=''">×</button></div>
    <div v-if="result?.absentTeachers.length" class="notice warning-notice">这些教师本学期没有课表：{{result.absentTeachers.join('、')}}</div>
    <section class="results-section"><div class="result-header"><div><h1>空闲时段</h1><span class="result-subtitle">{{result ? `${semester} · 第 ${week} 周 · ${selected.length} 位教师` : `${semester || '学期'} · 第 ${week} 周`}}</span></div><div class="filter-row"><button v-for="item in [{key:'ALL',label:'全部',cls:''},{key:'FREE',label:'全员空闲',cls:'free'},{key:'ONE_BUSY',label:'仅 1 人忙碌',cls:'one'},{key:'MANY_BUSY',label:'多人冲突',cls:'many'}]" :key="item.key" :class="['filter-chip',item.cls,{active:filter===item.key}]" @click="filter=item.key as any"><i></i>{{item.label}}<b>{{counts[item.key as keyof typeof counts]}}</b></button></div></div>
      <div class="matrix panel" role="grid" aria-label="一周空闲时段"><div class="matrix-corner">节次</div><div v-for="day in days" :key="day" class="day-heading">{{day}}</div><template v-for="slot in slots" :key="slot"><div class="slot-heading"><span>第 {{slotRange(slot)}} 节</span><small>({{slot.slice(0, 2)}}-{{slot.slice(2)}})</small></div><button v-for="day in [1,2,3,4,5,6,7]" :key="`${day}-${slot}`" :class="['time-cell',statusClass(getCell(day,slot)),{dim:filter!=='ALL'&&result&&getCell(day,slot)?.level!==filter,focused:selectedCell===getCell(day,slot)}]" role="gridcell" :aria-label="`${days[day-1]} ${slot} ${getCell(day,slot)?.level || '未查询'}`" @click="getCell(day,slot)&&chooseCell(getCell(day,slot)!)"><template v-if="result"><span class="cell-label">{{getCell(day,slot)?.level==='FREE'?'全员空闲':getCell(day,slot)?.level==='ONE_BUSY'?'仅 1 人忙碌':getCell(day,slot)?.level==='MANY_BUSY'?'多人冲突':'无数据'}}</span><small>{{getCell(day,slot)?.level==='FREE' ? '✓ 全部空闲' : getCell(day,slot)?.level==='ONE_BUSY' ? `👤 ${busyTeacher(getCell(day,slot))}` : getCell(day,slot)?.level==='MANY_BUSY' ? `${getCell(day,slot)?.busyCount ?? 0} 人有课` : '无数据'}}</small></template><template v-else><span class="placeholder-mark"></span><small>等待查询</small></template></button></template></div>
    </section>
    <Transition name="slide"><aside v-if="drawer==='cell'" class="drawer" aria-label="时段详情"><button class="icon-close" aria-label="关闭详情" @click="drawer=null">×</button><div class="drawer-eyebrow">时段详情</div><h2>{{days[(selectedCell?.dayOfWeek||1)-1]}} · {{selectedCell?.slotCode}}</h2><div class="detail-status" :class="selectedCell?.level.toLowerCase()">{{selectedCell?.level==='FREE'?'全员空闲':selectedCell?.level==='ONE_BUSY'?'仅 1 人忙碌':'多人冲突'}}<span>{{selectedCell?.busyCount}} 人</span></div><h3>有课教师</h3><p v-for="occupancy in selectedCell?.occupancies" :key="occupancy.teacherName+occupancy.courseName" class="occupancy"><b>{{occupancy.teacherName}}</b><span>{{occupancy.courseName}}</span></p><p v-if="!selectedCell?.occupancies.length" class="quiet">当前时段没有占用记录</p><h3>原始占用文本</h3><pre>{{selectedCell?.occupancies.map(o=>o.occupancyText).join('\n')||'无占用'}}</pre><button class="button secondary copy-button" @click="copyOccupancy">复制原文</button></aside></Transition>
    <Transition name="slide"><aside v-if="drawer==='college'" class="drawer college-drawer" aria-label="学院教师选择"><div class="college-header"><button class="icon-close" aria-label="关闭" @click="drawer=null">×</button><div class="drawer-eyebrow">教师筛选</div><h2>按学院/专业选人</h2><label class="field"><span>学院</span><select v-model="collegeSearch" @change="loadCollegeTeachers"><option value="">选择学院</option><option v-for="college in colleges" :key="college.code" :value="college.code">{{college.name}}</option></select></label><label v-if="collegeSearch" class="field"><span>专业名称</span><input v-model="collegeProgram" placeholder="按专业筛选"/></label><label v-if="collegeSearch" class="field"><span>教师姓名</span><input v-model="collegeTeacherQuery" type="search" placeholder="搜索已加载教师"/></label><div class="list-actions"><button class="text-button" @click="selectAllCollegeTeachers">全选当前列表</button><button class="text-button" @click="clearCollegeTeachers">清空当前列表</button></div></div><div class="teacher-check-list"><div class="teacher-card-grid"><label v-for="teacher in filteredTeachers" :key="teacher.name" class="teacher-check"><input type="checkbox" :checked="selected.includes(teacher.name)" @change="toggleCollegeTeacher(teacher.name)"/><span>{{teacher.name}}</span><small>{{teacherSubtitle(teacher)}}</small></label></div><p v-if="collegeSearch&&!filteredTeachers.length" class="quiet">没有匹配教师</p><p v-if="!collegeSearch" class="quiet">先选择学院</p></div><div class="drawer-footer"><span>{{selectedCollegeTeachers.length}} 位已选</span><div class="program-assignment"><label>设为专业</label><input v-model="programAssignment" :disabled="!selectedCollegeTeachers.length" placeholder="专业名称"/><button class="button secondary" :disabled="!selectedCollegeTeachers.length||!programAssignment.trim()||savingProgram" @click="saveProgram">保存专业</button><button class="button secondary" :disabled="!selectedCollegeTeachers.length||savingProgram" @click="clearProgram">清除专业</button></div><button class="button primary" @click="drawer=null">完成</button></div></aside></Transition>
    <div v-if="syncModal||importModal||missingModal" class="modal-backdrop" @click.self="closeModalBackdrop"><section v-if="missingModal" class="modal"><button class="icon-close" aria-label="关闭" @click="missingModal=false">×</button><div class="modal-icon">!</div><h2>这个学期还没有课表</h2><p>同步该学期课表后即可查询空闲时段。</p><button class="button primary modal-primary" @click="openSync">同步 {{semester}}</button></section>
      <section v-else-if="syncModal" class="modal sync-dialog"><button class="icon-close" aria-label="关闭" @click="closeSync">×</button><div class="drawer-eyebrow">课表同步</div><h2>同步课表</h2><template v-if="!syncBusy && !syncProgress"><label class="field modal-field"><span>学期</span><select v-model="semester"><option v-for="s in semesters" :key="s.code" :value="s.code">{{s.label}} · {{s.synced?'已同步':'未同步'}}</option></select></label><label class="field modal-field"><span>教务账号</span><input v-model="username" autocomplete="username" placeholder="留空则使用服务端 .env.local"/></label><label class="field modal-field"><span>教务密码</span><input v-model="password" type="password" autocomplete="current-password" placeholder="留空则使用服务端 .env.local"/></label><p v-if="syncError" class="notice error-notice modal-error" role="alert">{{syncError}}</p><button class="button primary modal-primary" :disabled="syncBusy" @click="startSync">{{syncBusy ? '正在同步…' : '立即同步'}}</button></template><template v-else><div v-if="slider" class="slider-form"><p>请按页面提示完成教务验证</p><div ref="sliderTrack" class="slider-track" :class="{dragging:sliderDragging}" @pointerdown="sliderPointerDown" @pointermove="sliderPointerMove" @pointerup="sliderPointerUp" @pointercancel="sliderPointerUp"><img class="slider-background" draggable="false" @dragstart.prevent :src="`data:image/png;base64,${slider.backgroundBase64}`" alt="滑块验证背景"/><img class="slider-piece" draggable="false" @dragstart.prevent :style="{transform:`translateX(${move}px)`}" :src="`data:image/png;base64,${slider.pieceBase64}`" alt="滑块验证拼图"/></div><div class="slider-hint">按住小图向右拖动，与缺口对齐后提交。</div><button class="button primary modal-primary" @click="submitSlider">提交滑块</button></div><div v-else class="sync-progress"><template v-if="syncProgress?.status !== 'DONE' && syncProgress?.status !== 'FAILED'"><div class="spinner"></div><b>{{syncProgress?.currentCollege ? `正在同步：${syncProgress.currentCollege} (${syncProgress.finishedColleges}/${syncProgress.totalColleges})` : '正在连接教务系统…'}}</b><div class="progress-track"><span :style="{width:`${syncProgress?.totalColleges ? syncProgress.finishedColleges/syncProgress.totalColleges*100 : 4}%`}"></span></div></template><p v-if="syncProgress?.status==='DONE'" class="sync-success" role="status">✅ {{syncProgress.semesterCode}} 学期同步成功！共更新 {{syncProgress.teacherCount}} 位教师课表</p><p v-if="syncProgress?.status==='DONE' && syncError" class="sync-failure" role="alert">{{syncError}}</p><p v-else-if="syncProgress?.status==='FAILED'" class="sync-failure" role="alert">{{syncError || '同步失败'}}</p></div><button v-if="syncProgress?.status==='FAILED'" class="button primary modal-primary" @click="syncBusy=false;syncProgress=null">重试</button><button v-else-if="syncProgress?.status==='DONE'" class="button secondary modal-primary" @click="closeSync">完成</button></template></section>
      <section v-else class="modal import-dialog"><button class="icon-close" aria-label="关闭" @click="importModal=false">×</button><div class="drawer-eyebrow">专业信息</div><h2>导入专业</h2><template v-if="!importResult"><label class="field"><span>名单文件</span><input type="file" accept=".csv,.txt,.tsv" @change="readImportFile"/></label><label class="field"><span>名单</span><textarea v-model="programText" rows="8" placeholder="每行可写 姓名,专业 或 姓名,学院,专业，使用 Tab 也可以"></textarea></label><button class="button primary modal-primary" @click="importPrograms">匹配并保存</button></template><div v-else class="import-summary"><div class="match-count"><b>{{importResult.matched}}</b><span>条匹配成功</span></div><p>未匹配姓名：{{importResult.unmatchedNames?.join('、') || '无'}}</p><p v-if="importResult.collegeMismatchNames?.length">学院不匹配：{{importResult.collegeMismatchNames.join('、')}}</p><button class="button primary modal-primary" @click="importModal=false">完成</button></div></section>
    </div>
  </main>
</template>
